-- Repair vehicle-log PDF templates. Their day row held {{#if is_weekend}}…{{else}}…
-- {{/if}} between table cells; the PDF editor (a real HTML parser) hoists those
-- helpers out of the table and keeps both branches' cells, so a template saved
-- from the editor printed every column twice. Replace only the day tables
-- (from {{#if is_odometer}} to the last </table>{{/if}}) with the current
-- layout: one cell per column, weekend shading from the entry's row_shade
-- colour, and narrow day / km columns so Customer / site does not wrap.
-- Everything a tenant edited above the tables is kept. Rows are tenant-scoped
-- under FORCE RLS, so each tenant is updated in its own context.
DO $$
DECLARE
  tenant uuid;
  previous_tenant text := current_setting('app.tenant_id', true);
  tables_pattern constant text := '\{\{#if is_odometer\}\}.*</table>\s*\{\{/if\}\}';
  source_tables constant text := $vl${{#if is_odometer}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:12%" /><col style="width:22%" /><col style="width:22%" /><col style="width:22%" /><col style="width:22%" /></colgroup><thead><tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Day</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Start odo</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">End odo</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Personal km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Total km</th></tr></thead><tbody><tr data-each="entries" bgcolor="{{row_shade}}" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{day}} {{weekday}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{start_odometer}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{end_odometer}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{total_km}}</td></tr><tr><td colspan="3" style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;font-weight:700;">Month total</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_total_km}}</td></tr></tbody></table>{{else}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:9%" /><col style="width:34%" /><col style="width:21%" /><col style="width:12%" /><col style="width:12%" /><col style="width:12%" /></colgroup><thead><tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Day</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Customer / site</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Other destination</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Business km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Personal km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Total km</th></tr></thead><tbody><tr data-each="entries" bgcolor="{{row_shade}}" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{day}} {{weekday}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{site_name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{other_destination}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{business_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{total_km}}</td></tr><tr><td colspan="3" style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;font-weight:700;">Month total</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_business_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_total_km}}</td></tr></tbody></table>{{/if}}$vl$;
  compiled_tables constant text := $vl${{#if is_odometer}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:12%"><col style="width:22%"><col style="width:22%"><col style="width:22%"><col style="width:22%"></colgroup><thead><tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Day</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Start odo</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">End odo</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Personal km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Total km</th></tr></thead><tbody>{{#each entries}}<tr bgcolor="{{row_shade}}" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{day}} {{weekday}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{start_odometer}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{end_odometer}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{total_km}}</td></tr>{{/each}}<tr><td colspan="3" style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;font-weight:700;">Month total</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_total_km}}</td></tr></tbody></table>{{else}}<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 10px;"><colgroup><col style="width:9%"><col style="width:34%"><col style="width:21%"><col style="width:12%"><col style="width:12%"><col style="width:12%"></colgroup><thead><tr><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Day</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Customer / site</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Other destination</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Business km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Personal km</th><th style="text-align:left;border:1px solid #e2e8f0;background:#f1f5f9;padding:5px 8px;font-size:10px;color:#475569;font-weight:700;text-transform:uppercase;letter-spacing:.3px;">Total km</th></tr></thead><tbody>{{#each entries}}<tr bgcolor="{{row_shade}}" style="page-break-inside:avoid;"><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{day}} {{weekday}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{site_name}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{other_destination}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{business_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{total_km}}</td></tr>{{/each}}<tr><td colspan="3" style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;font-weight:700;">Month total</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_business_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_personal_km}}</td><td style="border:1px solid #e2e8f0;padding:5px 8px;font-size:11.5px;color:#0f172a;vertical-align:top;padding:3px 4px;font-size:11px;line-height:1.2;">{{month_total_km}}</td></tr></tbody></table>{{/if}}$vl$;
BEGIN
  FOR tenant IN SELECT id FROM tenants LOOP
    PERFORM set_config('app.tenant_id', tenant::text, true);
    UPDATE pdf_templates
       SET source_html = replace(
             regexp_replace(source_html, tables_pattern, '__VEHICLE_LOG_TABLES__'),
             '__VEHICLE_LOG_TABLES__',
             source_tables
           ),
           compiled_html = replace(
             regexp_replace(compiled_html, tables_pattern, '__VEHICLE_LOG_TABLES__'),
             '__VEHICLE_LOG_TABLES__',
             compiled_tables
           ),
           updated_at = now()
     WHERE tenant_id = tenant
       AND record_subject_type = 'module'
       AND record_subject_key = 'vehicle-log'
       AND (source_html LIKE '%is_weekend%' OR compiled_html LIKE '%is_weekend%')
       AND source_html ~ tables_pattern
       AND compiled_html ~ tables_pattern;
  END LOOP;
  PERFORM set_config('app.tenant_id', coalesce(previous_tenant, ''), true);
END $$;
